import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath, pathToFileURL } from 'node:url';

const project = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const runtime = process.env.ONSEN_ASSEMBLY_RUNTIME || path.join(project, 'wechat/runtime/core');
const layoutPath = process.env.ONSEN_ASSEMBLY_LAYOUT || path.join(project, 'data/onsen-layout.json');
const core = (await import(pathToFileURL(path.join(runtime, 'GameSession.js')))).default;
const migration = (await import(pathToFileURL(path.join(runtime, 'ProgressMigration.js')))).default;
