const { GameSession, readyAssemblyStickers, patchStickerDraft, reorderDraft } = core;
const { migrateCompatibleProgress, compatibleProgressRevisions } = migration;
const { upgradeEditedAssemblyLayout, migrateEditedAssemblyProgress } = editedUpgrade;
const bytes = fs.readFileSync(layoutPath), layout = JSON.parse(bytes);
const clone = value => structuredClone(value), checks = [];
const check = (name, run) => { run(); checks.push({ name, passed: true }); };
const put = (session, id) => {
  assert.equal(session.select(id), true, `select ${id}`);
  const ticket = session.beginPlacement(id); assert.ok(ticket);
  assert.equal(session.commitPlacement(ticket), true, `commit ${id}`);
  if (session.getSnapshot().phase === 'transitioning') assert.equal(session.finishTransition(), true);
};
const restored = save => {
  const session = new GameSession(layout); assert.deepEqual(session.restore(save), { ok: true, errors: [] });
  assert.deepEqual(session.exportSave(), save); return session;
};
const legacyLayout = clone(layout); delete legacyLayout.assemblyPolicy;
legacyLayout.layoutRevision = 3;
for (const sticker of legacyLayout.stickers) sticker.areaLevel = layout.progressMigration.legacyAreaLevels[sticker.stickerId];
const expected = ['L004', 'L007', 'L011', 'L013', 'L014', 'L025'];
let walkedOrder = [];

check('all 161 pieces use structural, medium and detail stages without changing drawing order', () => {
  assert.equal(layout.layoutRevision, 4); assert.equal(layout.stickers.length, 161);
  assert.equal(layout.geoBlocks.length, 7); assert.equal(layout.renderOrder.length, 167);
  assert.deepEqual(compatibleProgressRevisions(layout, layout), [3, 2, 1]);
  assert.equal(layout.stickers.find(s => s.stickerId === 'L025').areaLevel, 'L2');
  for (const id of ['L019', 'L049', 'L050', 'C014', 'C017', 'C027', 'R005', 'L043', 'L044', 'L046', 'G008', 'G009']) {
    assert.equal(layout.stickers.find(s => s.stickerId === id).areaLevel, 'L1', `structural ${id}`);
  }
  const session = new GameSession(layout), painter = clone(layout.renderOrder), visited = [];
  const members = new Map(layout.geoBlocks.map(block => [block.blockId, layout.stickers.filter(s => s.geoBlock === block.blockId)]));
  assert.deepEqual(session.getSnapshot().availableStickerIds, ['L004']);
  assert.equal(session.select('L025'), false); assert.equal(session.select('L005'), false);
  while (session.getSnapshot().phase !== 'completed') {
    const snapshot = session.getSnapshot(), placed = new Set(snapshot.placedStickerIds);
    if (!visited.includes(snapshot.activeBlockId)) visited.push(snapshot.activeBlockId);
    const ready = members.get(snapshot.activeBlockId).filter(s => s.areaLevel === snapshot.activeAreaLevel
      && !placed.has(s.stickerId) && s.dependsOn.every(id => placed.has(id)));
    const low = Math.min(...ready.map(s => s.layerIndex));
    const expectedIDs = ready.filter(s => s.layerIndex === low)
      .sort((a, b) => b.effectiveAlphaArea * b.scale ** 2 - a.effectiveAlphaArea * a.scale ** 2 || a.placementOrder - b.placementOrder)
      .map(s => s.stickerId);
    assert.deepEqual(snapshot.availableStickerIds, expectedIDs);
    const id = snapshot.availableStickerIds[0]; assert.ok(id); walkedOrder.push(id); put(session, id);
    restored(session.exportSave()); assert.deepEqual(session.getLayout().renderOrder, painter);
  }
  assert.equal(walkedOrder.length, 161); assert.equal(new Set(walkedOrder).size, 161);
  assert.deepEqual(visited, layout.geoBlocks.slice().sort((a, b) => a.blockOrder - b.blockOrder).map(b => b.blockId));
  assert.deepEqual(session.getSnapshot().renderStickerIds, layout.stickers.slice().sort((a, b) => a.placementOrder - b.placementOrder).map(s => s.stickerId));
});

check('real supports unlock before lower-depth dependent pieces, without depth-order deadlock', () => {
  const item = (stickerId, layerIndex, effectiveAlphaArea, dependsOn = []) => ({ stickerId, areaLevel: 'L1', layerIndex,
    placementOrder: layerIndex + effectiveAlphaArea, effectiveAlphaArea, scale: 1, dependsOn });
  const pieces = [item('near-small', 80, 10), item('lower-small', 10, 20), item('lower-big', 10, 200),
    item('support', 40, 60), item('supported-back', 5, 10, ['support'])];
  const placed = new Set();
  assert.deepEqual(readyAssemblyStickers(pieces, 'L1', placed, layout.assemblyPolicy).map(s => s.stickerId), ['lower-big', 'lower-small']);
  placed.add('lower-big'); placed.add('lower-small');
  assert.deepEqual(readyAssemblyStickers(pieces, 'L1', placed, layout.assemblyPolicy).map(s => s.stickerId), ['support']);
  placed.add('support');
  assert.deepEqual(readyAssemblyStickers(pieces, 'L1', placed, layout.assemblyPolicy).map(s => s.stickerId), ['supported-back']);
});

check('every legal v3 chronological save prefix migrates with the exact same IDs and supports', () => {
  const previous = new GameSession(legacyLayout); let prefixes = 0;
  while (previous.getSnapshot().phase !== 'completed') {
    if (previous.getSnapshot().phase === 'transitioning') { previous.finishTransition(); continue; }
    const id = previous.getSnapshot().availableStickerIds[0]; assert.ok(id);
    assert.equal(previous.select(id), true); const ticket = previous.beginPlacement(id); assert.ok(ticket); previous.commitPlacement(ticket);
    const save = previous.exportSave(), untouched = clone(save);
    const candidate = migrateCompatibleProgress(layout, layout, save); assert.ok(candidate, `legacy prefix ${++prefixes}`);
    assert.deepEqual(candidate.placedStickerIds, save.placedStickerIds);
    assert.equal(candidate.legacyAssemblyPrefix.count, save.placedStickerIds.length);
    assert.equal(candidate.legacyAssemblyPrefix.sourceLayoutRevision, 3);
    restored(candidate); assert.deepEqual(save, untouched);
  }
  assert.equal(prefixes, 161);
});

check('six existing placements survive, missing structural pieces come next, undo and cold restore stay legal', () => {
  const old = new GameSession(legacyLayout); for (const id of expected) put(old, id);
  const previous = old.exportSave(), untouched = clone(previous);
  for (const revision of [3, 2, 1]) {
    const historical = { ...clone(previous), layoutRevision: revision };
    const save = migrateCompatibleProgress(layout, layout, historical); assert.ok(save); const session = restored(save);
    assert.deepEqual(session.getSnapshot().placedStickerIds, expected);
    assert.equal(session.getSnapshot().activeAreaLevel, 'L1');
    assert.deepEqual(session.getSnapshot().availableStickerIds, ['L049', 'L050']);
    assert.equal(session.select('L001'), false);
    put(session, 'L049'); assert.equal(session.exportSave().legacyAssemblyPrefix.count, 6);
    restored(session.exportSave()); assert.equal(session.undo(), true); assert.deepEqual(session.exportSave(), save);
    while (session.getSnapshot().phase !== 'completed') {
      const id = session.getSnapshot().availableStickerIds[0]; assert.ok(id); put(session, id); restored(session.exportSave());
    }
    assert.equal(session.getSnapshot().progress.placed, 161);
    assert.deepEqual(session.getSnapshot().placedStickerIds.slice(0, 6), expected);
    while (session.undo()) restored(session.exportSave());
    assert.equal(session.getSnapshot().progress.placed, 0); assert.equal(session.exportSave().legacyAssemblyPrefix, undefined);
    assert.deepEqual(session.getSnapshot().availableStickerIds, ['L004']);
  }
  assert.deepEqual(previous, untouched);
  assert.equal(migrateCompatibleProgress(layout, layout, previous, true), null);
});

check('bad legacy markers, wrong stages and skipped depth groups reject atomically', () => {
  const old = new GameSession(legacyLayout); for (const id of expected) put(old, id);
  const good = migrateCompatibleProgress(layout, layout, old.exportSave()), session = restored(good), before = session.getSnapshot();
  const invalid = [
    { ...clone(good), legacyAssemblyPrefix: { sourceLayoutRevision: 3, count: 0 } },
    { ...clone(good), legacyAssemblyPrefix: { sourceLayoutRevision: 3, count: 7 } },
    { ...clone(good), legacyAssemblyPrefix: { sourceLayoutRevision: 9, count: 6 } },
    { ...clone(good), legacyAssemblyPrefix: undefined },
    { ...clone(good), placedStickerIds: [...expected, 'L019'] },
    { ...clone(good), placedStickerIds: ['L005'], legacyAssemblyPrefix: { sourceLayoutRevision: 3, count: 1 } },
  ];
  for (const candidate of invalid) { assert.equal(session.restore(candidate).ok, false); assert.deepEqual(session.getSnapshot(), before); }
});

check('old edited revision 4 upgrades separately while preserving transforms, paint queue, storage and real edited stages', () => {
  let edited = clone(legacyLayout); edited.layoutRevision = 4;
  const cabinet = edited.stickers.find(s => s.stickerId === 'L007');
  edited = patchStickerDraft(edited, 'L007', { position: { x: cabinet.position.x + 21, y: cabinet.position.y + 11 }, scale: 1.13, rotation: 8 });
  edited = reorderDraft(patchStickerDraft(edited, 'L011', { layerIndex: 46 }));
  // A genuine old user stage edit: this lamp was explicitly made a detail.
  edited = patchStickerDraft(edited, 'C015', { areaLevel: 'L3' });
  const old = new GameSession(edited); for (const id of expected) put(old, id);
  const historical = old.exportSave(), beforeEdited = clone(edited), beforeSave = clone(historical), beforeSource = clone(layout);
  const storage = new Map([[`old-layout:${edited.layoutRevision}`, edited], [`old-progress:${edited.layoutRevision}`, historical]]);
  const storageBefore = JSON.stringify([...storage]);
  const upgrade = upgradeEditedAssemblyLayout(layout, edited); assert.ok(upgrade);
  assert.equal(upgrade.layout.layoutRevision, 5); assert.equal(upgrade.previousLayoutRevision, 4);
  assert.deepEqual(upgrade.layout.renderOrder, edited.renderOrder); assert.deepEqual(upgrade.layout.fixedLayers, edited.fixedLayers);
  for (const previous of edited.stickers) {
    const next = upgrade.layout.stickers.find(s => s.stickerId === previous.stickerId);
    for (const field of ['position', 'scale', 'rotation', 'anchor', 'layerIndex', 'placementOrder', 'geoBlock', 'assetKey', 'sourceSize', 'renderParts']) {
      assert.deepEqual(next[field], previous[field], `preserve ${previous.stickerId}.${field}`);
    }
  }
  assert.equal(upgrade.layout.progressMigration.legacyAreaLevels.C015, 'L3', 'use real edited historical stages');
  assert.equal(upgrade.layout.stickers.find(s => s.stickerId === 'C015').areaLevel, 'L1');
  const entireOld = new GameSession(edited); let editedPrefixes = 0;
  while (entireOld.getSnapshot().phase !== 'completed') {
    const id = entireOld.getSnapshot().availableStickerIds[0]; assert.ok(id); put(entireOld, id);
    const prefix = migrateEditedAssemblyProgress(upgrade, entireOld.exportSave()); assert.ok(prefix, `edited historical prefix ${++editedPrefixes}`);
    const loaded = new GameSession(upgrade.layout); assert.deepEqual(loaded.restore(prefix), { ok: true, errors: [] });
    assert.deepEqual(loaded.getSnapshot().placedStickerIds, entireOld.getSnapshot().placedStickerIds);
  }
  assert.equal(editedPrefixes, 161);
  const migrated = migrateEditedAssemblyProgress(upgrade, historical); assert.ok(migrated);
  assert.deepEqual(migrated.placedStickerIds, expected); assert.equal(migrated.legacyAssemblyPrefix.sourceLayoutRevision, 4);
  const session = new GameSession(upgrade.layout); assert.deepEqual(session.restore(migrated), { ok: true, errors: [] });
  assert.deepEqual(session.getSnapshot().availableStickerIds, ['L049', 'L050']);
  put(session, 'L049'); const latest = session.exportSave(), cold = new GameSession(upgrade.layout);
  assert.deepEqual(cold.restore(latest), { ok: true, errors: [] }); assert.equal(cold.undo(), true);
  assert.deepEqual(cold.exportSave(), migrated);
  assert.equal(upgradeEditedAssemblyLayout(layout, upgrade.layout), null, 'already-current edited upgrade is idempotent');
  assert.deepEqual(edited, beforeEdited); assert.deepEqual(historical, beforeSave); assert.deepEqual(layout, beforeSource);
  assert.equal(JSON.stringify([...storage]), storageBefore, 'pure upgrade never removes or writes original storage keys');
  assert.equal(migrateEditedAssemblyProgress(upgrade, { ...historical, placedStickerIds: ['L005'] }), null, 'real support dependency still required');
});

const result = { passed: true, layoutRevision: layout.layoutRevision,
  currentLayoutSHA256: crypto.createHash('sha256').update(bytes).digest('hex'),
  logicalStickers: 161, blocks: 7, checks, legalAssemblyOrder: walkedOrder,
  scope: 'pure state and migration tests; no camera, native device or visual-art certification' };
const output = process.env.ONSEN_ASSEMBLY_RESULT || path.join(project, 'tests/assembly-order-results.json');
fs.mkdirSync(path.dirname(output), { recursive: true }); fs.writeFileSync(output, JSON.stringify(result, null, 2) + '\n');
